import type { Catalog, Category, Product } from './catalog-model';
import { SUPPORTED_SCHEMA_VERSION } from './catalog-model';

/**
 * The trust boundary for `data/catalog.json`.
 *
 * The document is generated by `scripts/build-catalog.mjs` and is the store's single source
 * of truth, but it is still *data*: nothing guarantees its shape at the moment it is read
 * at runtime. A blind cast would turn a generator change into `undefined` rendered into the
 * page, an `<img src="undefined">` or a price of `NaN` — failures that are hard to trace
 * back to their cause. So every field is checked here, once, and a drift produces a message
 * that names the exact JSON path and what was expected.
 *
 * This module is pure: no Angular, no DOM, no I/O. It takes whatever `JSON.parse` produced
 * and either returns a normalised {@link Catalog} or throws {@link CatalogValidationError}.
 *
 * Validation is deliberately collection-based: it reports *every* issue it finds rather than
 * stopping at the first, because the usual cause is one generator regression that affects
 * many records, and seeing the whole set at once is what makes it diagnosable.
 */

/** How many issues the thrown message lists before it summarises the rest. */
const MAX_REPORTED_ISSUES = 25;

/** Thrown when the catalog document does not match the contract. */
export class CatalogValidationError extends Error {
  /** Every issue found, not only the ones included in the message. */
  readonly issues: readonly string[];

  constructor(issues: readonly string[]) {
    const shown = issues.slice(0, MAX_REPORTED_ISSUES);
    const hidden = issues.length - shown.length;
    super(
      [
        `catalog.json failed validation with ${issues.length} issue(s):`,
        ...shown.map((issue) => `  - ${issue}`),
        ...(hidden > 0 ? [`  - ...and ${hidden} more`] : []),
      ].join('\n'),
    );
    this.name = 'CatalogValidationError';
    this.issues = issues;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Renders an unexpected value for an error message, without dumping a whole document. */
function describeValue(value: unknown): string {
  if (value === null) return 'null';
  if (value === undefined) return 'undefined';
  if (typeof value === 'string') {
    return value.length > 40 ? `a string starting "${value.slice(0, 40)}..."` : `"${value}"`;
  }
  if (Array.isArray(value)) return `an array of ${value.length}`;
  if (typeof value === 'object') return 'an object';
  return `a ${typeof value} (${String(value)})`;
}

/** Reads a required non-empty string. Returns `undefined` after recording the issue. */
function readNonEmptyString(
  source: Record<string, unknown>,
  key: string,
  path: string,
  issues: string[],
): string | undefined {
  const value = source[key];
  if (typeof value !== 'string') {
    issues.push(`${path}: expected a string, received ${describeValue(value)}`);
    return undefined;
  }
  if (value.trim().length === 0) {
    issues.push(`${path}: expected a non-empty string, received an empty one`);
    return undefined;
  }
  return value;
}

/** Reads a required string that is allowed to be empty. */
function readString(
  source: Record<string, unknown>,
  key: string,
  path: string,
  issues: string[],
): string | undefined {
  const value = source[key];
  if (typeof value !== 'string') {
    issues.push(`${path}: expected a string, received ${describeValue(value)}`);
    return undefined;
  }
  return value;
}

/** Reads a required finite number. */
function readFiniteNumber(
  source: Record<string, unknown>,
  key: string,
  path: string,
  issues: string[],
): number | undefined {
  const value = source[key];
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    issues.push(`${path}: expected a finite number, received ${describeValue(value)}`);
    return undefined;
  }
  return value;
}

function readArray(
  source: Record<string, unknown>,
  key: string,
  path: string,
  issues: string[],
): readonly unknown[] | undefined {
  const value = source[key];
  if (!Array.isArray(value)) {
    issues.push(`${path}: expected an array, received ${describeValue(value)}`);
    return undefined;
  }
  return value;
}

/**
 * Reads a root-relative asset path that may legitimately be `null`.
 *
 * Absence and a malformed value are different outcomes: a missing banner is normal (3 of 10
 * categories), but a value that is not root-relative would produce a 404 in the browser, so
 * that is reported. Returns `undefined` only to mean "invalid, already reported".
 */
function readAssetPath(
  source: Record<string, unknown>,
  key: string,
  path: string,
  issues: string[],
): string | null | undefined {
  const value = source[key];
  if (value === null) return null;
  if (typeof value !== 'string') {
    issues.push(`${path}: expected a root-relative path or null, received ${describeValue(value)}`);
    return undefined;
  }
  if (!value.startsWith('/')) {
    issues.push(
      `${path}: expected a root-relative path starting with "/", received "${value}" — ` +
        'a relative path would resolve against the current route and 404',
    );
    return undefined;
  }
  // Stored root-absolute, handed out document-relative. The app is served from a sub-path on
  // GitHub Pages (`/yokai-hardcore-store/`), so the leading slash has to go: the browser would
  // otherwise resolve the path against the domain root and 404. Without it, `<base href>` — which
  // already carries the deployment prefix — decides where the asset lives, on every route.
  return value.slice(1);
}

/**
 * Reads a root-relative path that may be `null`, without requiring the leading slash.
 *
 * Used for `modelPath`, whose interpretation belongs to the 3D layer and which may one day
 * be an absolute URL; today every product has `null` there.
 */
function readNullableString(
  source: Record<string, unknown>,
  key: string,
  path: string,
  issues: string[],
): string | null | undefined {
  const value = source[key];
  if (value === null) return null;
  if (typeof value !== 'string' || value.trim().length === 0) {
    issues.push(`${path}: expected a non-empty string or null, received ${describeValue(value)}`);
    return undefined;
  }
  return value;
}

function parseCategories(rawList: readonly unknown[], issues: string[]): Category[] {
  const categories: Category[] = [];
  rawList.forEach((item, index) => {
    const path = `categories[${index}]`;
    if (!isRecord(item)) {
      issues.push(`${path}: expected an object, received ${describeValue(item)}`);
      return;
    }
    // `productCount` is read here only to cross-check it against the products below; the
    // normalised category deliberately does not keep it.
    const productCount = readFiniteNumber(item, 'productCount', `${path}.productCount`, issues);
    const id = readNonEmptyString(item, 'id', `${path}.id`, issues);
    const slug = readNonEmptyString(item, 'slug', `${path}.slug`, issues);
    const name = readNonEmptyString(item, 'name', `${path}.name`, issues);
    const description = readString(item, 'description', `${path}.description`, issues);
    const bannerImage = readAssetPath(item, 'bannerImage', `${path}.bannerImage`, issues);

    if (
      id === undefined ||
      slug === undefined ||
      name === undefined ||
      description === undefined ||
      bannerImage === undefined ||
      productCount === undefined
    ) {
      return;
    }
    if (!Number.isInteger(productCount) || productCount < 0) {
      issues.push(`${path}.productCount: expected a non-negative integer, received ${productCount}`);
      return;
    }
    categories.push({ id, slug, name, description, bannerImage });
  });
  return categories;
}

function parseProducts(rawList: readonly unknown[], issues: string[]): Product[] {
  const products: Product[] = [];
  rawList.forEach((item, index) => {
    const path = `products[${index}]`;
    if (!isRecord(item)) {
      issues.push(`${path}: expected an object, received ${describeValue(item)}`);
      return;
    }
    const id = readNonEmptyString(item, 'id', `${path}.id`, issues);
    const slug = readNonEmptyString(item, 'slug', `${path}.slug`, issues);
    const name = readNonEmptyString(item, 'name', `${path}.name`, issues);
    const categoryId = readNonEmptyString(item, 'categoryId', `${path}.categoryId`, issues);
    const description = readString(item, 'description', `${path}.description`, issues);
    const priceUsd = readFiniteNumber(item, 'priceUsd', `${path}.priceUsd`, issues);
    const imagePath = readAssetPath(item, 'localImage', `${path}.localImage`, issues);
    const modelPath = readNullableString(item, 'modelPath', `${path}.modelPath`, issues);

    if (
      id === undefined ||
      slug === undefined ||
      name === undefined ||
      categoryId === undefined ||
      description === undefined ||
      priceUsd === undefined ||
      imagePath === undefined ||
      modelPath === undefined
    ) {
      return;
    }
    if (priceUsd <= 0) {
      issues.push(`${path}.priceUsd: expected a positive number, received ${priceUsd}`);
      return;
    }
    products.push({ id, slug, name, priceUsd, categoryId, description, imagePath, modelPath });
  });
  return products;
}

/** Records an issue for every value that occurs more than once in a collection. */
function checkUnique(
  items: readonly { readonly id: string; readonly slug: string }[],
  collection: string,
  key: 'id' | 'slug',
  issues: string[],
): void {
  const seen = new Map<string, number>();
  items.forEach((item, index) => {
    const value = item[key];
    const first = seen.get(value);
    if (first === undefined) {
      seen.set(value, index);
      return;
    }
    issues.push(
      `${collection}[${index}].${key}: duplicate ${key} "${value}", already used by ${collection}[${first}]`,
    );
  });
}

/** Records an issue for every product whose `categoryId` names no category. */
function checkReferentialIntegrity(
  categories: readonly Category[],
  products: readonly Product[],
  issues: string[],
): void {
  const known = new Set(categories.map((category) => category.id));
  products.forEach((product, index) => {
    if (!known.has(product.categoryId)) {
      issues.push(
        `products[${index}].categoryId: "${product.categoryId}" does not match any ` +
          'categories[].id, so this product would have no category to belong to',
      );
    }
  });
}

/**
 * Cross-checks each category's declared `productCount` against the products that actually
 * reference it. The declared count is what the category card shows, so a generator change
 * that orphaned or miscounted products would otherwise display a lie.
 */
function checkDeclaredProductCounts(
  rawCategories: readonly unknown[],
  products: readonly Product[],
  issues: string[],
): void {
  const actual = new Map<string, number>();
  for (const product of products) {
    actual.set(product.categoryId, (actual.get(product.categoryId) ?? 0) + 1);
  }
  rawCategories.forEach((raw, index) => {
    if (!isRecord(raw)) return;
    const id = raw['id'];
    const declared = raw['productCount'];
    if (typeof id !== 'string' || typeof declared !== 'number') return;
    const found = actual.get(id) ?? 0;
    if (found !== declared) {
      issues.push(
        `categories[${index}].productCount: declared ${declared} but ${found} product(s) ` +
          `reference "${id}"`,
      );
    }
  });
}

/**
 * Validates and normalises a parsed catalog document.
 *
 * @throws {CatalogValidationError} listing every issue found.
 */
export function parseCatalogResponse(raw: unknown): Catalog {
  if (!isRecord(raw)) {
    throw new CatalogValidationError([
      `root: expected an object with "schemaVersion", "categories" and "products", received ${describeValue(raw)}`,
    ]);
  }

  const issues: string[] = [];
  const schemaVersion = readFiniteNumber(raw, 'schemaVersion', 'schemaVersion', issues);
  if (schemaVersion !== undefined && schemaVersion !== SUPPORTED_SCHEMA_VERSION) {
    issues.push(
      `schemaVersion: this build reads version ${SUPPORTED_SCHEMA_VERSION} only, received ` +
        `${schemaVersion} — regenerate the catalog with \`npm run catalog:build\``,
    );
  }

  const rawCategories = readArray(raw, 'categories', 'categories', issues) ?? [];
  const rawProducts = readArray(raw, 'products', 'products', issues) ?? [];

  const categories = parseCategories(rawCategories, issues);
  const products = parseProducts(rawProducts, issues);

  checkUnique(categories, 'categories', 'id', issues);
  checkUnique(categories, 'categories', 'slug', issues);
  checkUnique(products, 'products', 'id', issues);
  checkUnique(products, 'products', 'slug', issues);
  checkReferentialIntegrity(categories, products, issues);
  checkDeclaredProductCounts(rawCategories, products, issues);

  if (issues.length > 0) throw new CatalogValidationError(issues);

  return { schemaVersion: SUPPORTED_SCHEMA_VERSION, categories, products };
}
